# ── Client ────────────────────────────────────────────────────────────────────────────────────────


class PlatformClient(ManagementClient):
    """Cbox ID — Operator API.

    The **deployment itself**, for the staff who run it: stand up customer workspaces,
    create and bootstrap environments, manage organizations inside any environment, and
    keep the operator roster. Everything the console's Platform pages do, as the same
    actions — the same rules, refusals and audit trail.

    ``base_url`` defaults to ``https://api.cboxid.com``.
    """

    _plane = "platform"
    _default_base_url = "https://api.cboxid.com"

    def _bind(self, core: ManagementTransport) -> None:
        self.action_approvals = ActionApprovalsMethods(core)
        self.environments = EnvironmentsMethods(core)
        self.operators = OperatorsMethods(core)
        self.organizations = OrganizationsMethods(core)
        self.workspaces = WorkspacesMethods(core)
